using System.IO;
using System.Xml.Linq;
using Xunit;

namespace PubTemplateEditor.Integration.Tests;

/// <summary>
/// The application's own artwork: what the executable, the window and the MSIX tiles are built from.
/// The files are generated by tools/brand/generate-brand-assets.ps1 and committed, so a build never
/// needs to run the generator - and a broken or placeholder asset therefore fails a test instead of
/// shipping a blank tile.
/// </summary>
public class BrandAssetTests
{
    private static string RepoRoot()
    {
        DirectoryInfo? dir = new(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "PubTemplateEditor.slnx")))
        {
            dir = dir.Parent;
        }

        return dir!.FullName;
    }

    private static string Path_(params string[] parts) => Path.Combine(new[] { RepoRoot() }.Concat(parts).ToArray());

    [Fact]
    public void TheExecutableIconCarriesEverySizeTheShellAndTaskbarAskFor()
    {
        string ico = Path_("src", "PubTemplateEditor.App", "Assets", "app.ico");
        Assert.True(File.Exists(ico), "the application icon is missing: " + ico);

        using FileStream stream = File.OpenRead(ico);
        using BinaryReader reader = new(stream);

        Assert.Equal((ushort)0, reader.ReadUInt16());  // reserved
        Assert.Equal((ushort)1, reader.ReadUInt16());  // type: icon
        ushort count = reader.ReadUInt16();
        Assert.True(count >= 6, $"the icon carries only {count} sizes; taskbar, window and tiles need several");

        var sizes = new List<int>();
        for (int i = 0; i < count; i++)
        {
            int width = reader.ReadByte();
            int height = reader.ReadByte();
            reader.ReadByte();                        // palette entries
            reader.ReadByte();                        // reserved
            Assert.Equal((ushort)1, reader.ReadUInt16());   // colour planes
            Assert.Equal((ushort)32, reader.ReadUInt16());  // bits per pixel
            uint length = reader.ReadUInt32();
            uint offset = reader.ReadUInt32();

            width = width == 0 ? 256 : width;
            height = height == 0 ? 256 : height;
            Assert.True(width == height, "an application icon frame must be square");

            long position = stream.Position;
            stream.Position = offset;
            byte[] frame = reader.ReadBytes((int)length);
            stream.Position = position;

            Assert.True(length > 0 && frame.Length == length, "an icon frame points outside the file");
            Assert.Equal(width, PngWidth(frame));
            Assert.Equal(height, PngHeight(frame));
            sizes.Add(width);
        }

        foreach (int needed in new[] { 16, 24, 32, 48, 256 })
        {
            Assert.Contains(needed, sizes);
        }
    }

    [Fact]
    public void EveryTileTheManifestNamesExistsAtItsOwnSize()
    {
        string manifest = File.ReadAllText(Path_("packaging", "AppxManifest.template.xml"));
        XNamespace uap = "http://schemas.microsoft.com/appx/manifest/uap/windows10";
        XDocument document = XDocument.Parse(manifest);

        var expected = new (string File, int Width, int Height)[]
        {
            ("Square44x44Logo.png", 44, 44),
            ("Square71x71Logo.png", 71, 71),
            ("Square150x150Logo.png", 150, 150),
            ("Square310x310Logo.png", 310, 310),
            ("Wide310x150Logo.png", 310, 150),
            ("StoreLogo.png", 50, 50),
            ("SplashScreen.png", 620, 300),
        };

        foreach ((string name, int width, int height) in expected)
        {
            Assert.Contains(name, manifest, StringComparison.Ordinal);
            string path = Path_("packaging", "assets", name);
            Assert.True(File.Exists(path), "the manifest names a tile that is not in the repository: " + name);

            byte[] bytes = File.ReadAllBytes(path);
            Assert.Equal(width, PngWidth(bytes));
            Assert.Equal(height, PngHeight(bytes));
            Assert.True(bytes.Length > 200, name + " looks like a placeholder, not artwork");
        }
    }

    [Fact]
    public void TheProjectAndTheWindowsPointAtTheSameIcon()
    {
        string project = File.ReadAllText(Path_("src", "PubTemplateEditor.App", "PubTemplateEditor.App.csproj"));
        Assert.Contains("<ApplicationIcon>Assets", project, StringComparison.Ordinal);
        Assert.Contains("app.ico", project, StringComparison.Ordinal);

        // The window icon is a pack URI into this assembly, so it also resolves from a single-file
        // executable and from a test host - the same reason the theme dictionaries use one.
        foreach (string window in new[] { "MainWindow.xaml", "LicensesWindow.xaml", "UnsavedWorkWindow.xaml" })
        {
            string xaml = File.ReadAllText(Path_("src", "PubTemplateEditor.App", window));
            Assert.Contains(
                "Icon=\"pack://application:,,,/PUB_Template_Parameter_Editor;component/Assets/app.ico\"",
                xaml, StringComparison.Ordinal);
            Assert.Contains("<Resource Include=\"Assets\\app.ico\"",
                File.ReadAllText(Path_("src", "PubTemplateEditor.App", "PubTemplateEditor.App.csproj")),
                StringComparison.Ordinal);
        }
    }

    [Fact]
    public void TheArtworkIsGeneratedByThisRepositoryAndNotDownloaded()
    {
        string generator = Path_("tools", "brand", "generate-brand-assets.ps1");
        Assert.True(File.Exists(generator), "the artwork generator must live in the repository: " + generator);

        string text = File.ReadAllText(generator);
        Assert.Contains("RenderTargetBitmap", text, StringComparison.Ordinal);
        Assert.Contains("app.ico", text, StringComparison.Ordinal);
        Assert.DoesNotContain("Invoke-WebRequest", text, StringComparison.Ordinal);
        Assert.DoesNotContain("DownloadFile", text, StringComparison.Ordinal);

        // Provenance is recorded where the licence notices are, not only in a commit message.
        string notice = File.ReadAllText(Path_("NOTICE"));
        Assert.Contains("artwork", notice, StringComparison.OrdinalIgnoreCase);
    }

    private static int PngWidth(byte[] png) =>
        (png[16] << 24) | (png[17] << 16) | (png[18] << 8) | png[19];

    private static int PngHeight(byte[] png) =>
        (png[20] << 24) | (png[21] << 16) | (png[22] << 8) | png[23];
}
